import React from 'react';
import './footer.css';

const Footer = () => {
  const currentYear = new Date().getFullYear();

  return (
    <footer>
      <h3>Thank You For Visiting!</h3>
      <span> &copy; {currentYear} | Sudeshna Pandey・All rights reserved</span>
    </footer>
  );
};

export default Footer;
